TEST(OpponentDetectorTest, CloseRangePhantomRejected)
{
  const CircleTrack t = makeCircle(20.0, 120, 1.5);
  ObsConfig cfg;
  TrackObservationBuilder builder(t.xs, t.ys, t.wl, t.wr, cfg);
  DetectorConfig dcfg;
  OpponentDetector det(builder, dcfg);

  // Bumper-range phantom ~0.3 m ahead of ego at the origin.
  const auto phantom = carBlobScan(0.3, 0.0, 5, 0.04);
  const auto clusters = det.cluster(phantom);
  ASSERT_EQ(clusters.size(), 1u);
  EXPECT_LT(det.clusterNearEdgeDist(phantom, clusters[0], 0.0, 0.0), 0.35);
  EXPECT_FALSE(det.standsOut(phantom, clusters[0], 0.0, 0.0));

  DetectionResult res;
  for (int k = 0; k < 5; ++k) {
    res = det.update(phantom, 0.0, 0.0, 0.1 * k);
  }
  EXPECT_FALSE(res.present);
}

