TEST(OpponentDetectorTest, ReplayGymScanFixture)
{
  // Schema (written by test/record_gym_scan_fixture.py):
  // { "track_csv": "optional/path.csv",
  //   "frames": [ { "ranges": [...], "angle_min", "angle_increment",
  //                 "ego_x", "ego_y", "ego_yaw", "opp_x", "opp_y" }, ... ] }
  const std::string path = gymScanFixturePath();
  std::vector<GymScanFrame> frames;
  std::string track_csv;
  if (!loadGymScanFixture(path, frames, &track_csv)) {
    GTEST_SKIP() << "gym scan fixture not found or unreadable: " << path;
  }
  ASSERT_FALSE(frames.empty());

#ifdef IV2026_TRACK_CSV_PATH
  if (track_csv.empty()) {
    track_csv = IV2026_TRACK_CSV_PATH;
  }
#endif
  ObsConfig cfg;
  std::unique_ptr<TrackObservationBuilder> builder;
  if (!track_csv.empty()) {
    try {
      const TrackData track = loadTrackCsv(track_csv);
      builder = std::make_unique<TrackObservationBuilder>(
        track.x, track.y, track.w_left, track.w_right, cfg);
    } catch (const std::exception & e) {
      GTEST_SKIP() << "cannot load track_csv '" << track_csv << "': " << e.what();
    }
  } else {
    const CircleTrack t = makeCircle(20.0, 120, 1.5);
    builder = std::make_unique<TrackObservationBuilder>(
      t.xs, t.ys, t.wl, t.wr, cfg);
  }

  DetectorConfig dcfg;
  OpponentDetector det(*builder, dcfg);

  int gt_visible = 0;
  int confirmed = 0;
  double sum_err = 0.0;
  for (size_t f = 0; f < frames.size(); ++f) {
    const GymScanFrame & frame = frames[f];
    ASSERT_FALSE(frame.ranges.empty());
    const auto beams = rangesToMapBeams(
      frame.ranges, frame.angle_min, frame.angle_increment,
      frame.ego_x, frame.ego_y, frame.ego_yaw);
    const DetectionResult res = det.update(
      beams, frame.ego_x, frame.ego_y, 0.1 * static_cast<double>(f),
      frame.angle_increment);

    const bool has_gt =
      std::isfinite(frame.opp_x) && std::isfinite(frame.opp_y) &&
      (std::abs(frame.opp_x) > 1e-6 || std::abs(frame.opp_y) > 1e-6);
    if (!has_gt) {
      continue;
    }
    ++gt_visible;
    if (res.present) {
      ++confirmed;
      const double dx = res.pos_x - frame.opp_x;
      const double dy = res.pos_y - frame.opp_y;
      sum_err += std::sqrt(dx * dx + dy * dy);
    }
  }
  if (gt_visible == 0) {
    GTEST_SKIP() << "fixture has no GT opponent frames";
  }
  const double recall = static_cast<double>(confirmed) / static_cast<double>(gt_visible);
  EXPECT_GT(recall, 0.5) << "recall on recorded gym fixture";
  if (confirmed > 0) {
    EXPECT_LT(sum_err / confirmed, 1.5) << "mean position error (m)";
  }
}

TEST(RlObsCore, LagFilter)
{
  EXPECT_NEAR(f1tenth_rl_vehicle::lagAlpha(0.1, 0.1), 0.5, 1e-9);
  EXPECT_NEAR(f1tenth_rl_vehicle::stepFirstOrderLag(0.0, 1.0, 0.5), 0.5, 1e-9);
  EXPECT_NEAR(f1tenth_rl_vehicle::stepFirstOrderLag(0.5, 1.0, 0.5), 0.75, 1e-9);
}

TEST(RlObsCore, MapActionToForce)
{
  auto [long_cmd, steer] =
    f1tenth_rl_vehicle::mapActionToForce(0.5, -0.5, 0.44, 1.0);
  EXPECT_NEAR(long_cmd, 0.5, 1e-9);
  EXPECT_NEAR(steer, -0.22, 1e-9);

  auto [brake_cmd, steer0] =
    f1tenth_rl_vehicle::mapActionToForce(-0.8, 0.0, 0.44, 1.0);
  EXPECT_NEAR(brake_cmd, -0.8, 1e-9);
  EXPECT_NEAR(steer0, 0.0, 1e-9);

  auto [clipped, steer_clip] =
    f1tenth_rl_vehicle::mapActionToForce(5.0, -5.0, 0.44, 1.0);
  EXPECT_NEAR(clipped, 1.0, 1e-9);
  EXPECT_NEAR(steer_clip, -0.44, 1e-9);
}
